-- A shipment carries what goods cost to bring in. It is read by the owner and whoever keeps or
-- checks the books, and written by the owner and an accountant, in the branches they work in.
CREATE POLICY shipments_select ON public.shipments FOR SELECT TO app_runtime
  USING (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'auditor')
    AND ((SELECT app.tenant_branch_ids()) IS NULL OR branch_id = ANY ((SELECT app.tenant_branch_ids())::uuid[]))
  );
--> statement-breakpoint
CREATE POLICY shipments_insert ON public.shipments FOR INSERT TO app_runtime
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant')
    AND status = 'open'
    AND created_by = (SELECT app.current_user_id())
    AND updated_by = (SELECT app.current_user_id())
    AND ((SELECT app.tenant_branch_ids()) IS NULL OR branch_id = ANY ((SELECT app.tenant_branch_ids())::uuid[]))
  );
--> statement-breakpoint
