-- The journal that spreads a shipment's charges stands with the row written for that
-- spreading. It carries no number of its own, and is never reversed: it has no function for a
-- reversal, so one is refused.
CREATE FUNCTION app.journal_backed_landed_cost(p_journal public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
