      SELECT 1 FROM public.shipment_allocations a
      WHERE a.tenant_id = p_journal.tenant_id AND a.id = p_journal.source_id AND a.journal_id = p_journal.id AND a.allocated_on = p_journal.journal_date)
  $$;
