-- ── hand-written: what a bill charged to Goods in transit ───────────────────────────────────────
-- A line of a bill may now be charged to Goods in transit, the one locked account a bill can
-- name: import charges wait there until they are spread over a shipment. Step 25's guard,
-- written out again with that one change; the rest is drizzle/0030_supplier_bills.sql word for
-- word.
CREATE OR REPLACE FUNCTION app.check_supplier_bill_line() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid;
  v_bill public.supplier_bills%ROWTYPE;
  v_scope uuid[] := app.tenant_branch_ids();
BEGIN
  IF session_user = 'postgres' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    v_tenant := OLD.tenant_id;
  ELSE
    v_tenant := NEW.tenant_id;
  END IF;
  IF v_tenant IS DISTINCT FROM app.tenant_id() THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  -- Held the way an update holds a row: two sessions that each add a line and then post would
  -- otherwise each wait for the other to let go.
  SELECT d.* INTO v_bill FROM public.supplier_bills d
    WHERE d.tenant_id = v_tenant AND d.id = (CASE WHEN TG_OP = 'DELETE' THEN OLD.bill_id ELSE NEW.bill_id END)
    FOR NO KEY UPDATE;
  IF TG_OP = 'UPDATE' THEN
    IF NOT FOUND OR v_bill.status <> 'draft'
       OR (to_jsonb(NEW) - 'received_value') IS DISTINCT FROM (to_jsonb(OLD) - 'received_value') THEN
      RAISE EXCEPTION 'a line of a bill is replaced, not changed' USING ERRCODE = 'SE226';
    END IF;
    RETURN NEW;
  END IF;
  -- A line of no bill is left for the foreign key to refuse. Anything else is said only to a
  -- member who could have written the bill: anyone else is refused by the policies, in the same
  -- words as for a bill that is not there at all.
  IF FOUND AND app.tenant_role() IN ('owner', 'accountant') AND (v_scope IS NULL OR v_bill.branch_id = ANY (v_scope)) THEN
    IF v_bill.status <> 'draft' THEN
      RAISE EXCEPTION 'a line is written only while its bill is a draft' USING ERRCODE = 'SE226';
    END IF;
    IF TG_OP = 'INSERT' THEN
      IF NEW.received_value IS NOT NULL THEN
        RAISE EXCEPTION 'what a line cleared is worked out when the bill is posted' USING ERRCODE = 'SE226';
      END IF;
      IF NEW.kind = 'goods' AND NOT EXISTS (
        SELECT 1 FROM public.goods_receipt_lines g
        JOIN public.goods_receipts r ON r.tenant_id = g.tenant_id AND r.id = g.receipt_id
        JOIN public.warehouses w ON w.tenant_id = r.tenant_id AND w.id = r.warehouse_id
        WHERE g.tenant_id = v_tenant AND g.id = NEW.receipt_line_id AND g.item_id = NEW.item_id AND g.quantity >= NEW.quantity
          AND r.status = 'posted' AND r.supplier_id = v_bill.supplier_id AND w.branch_id = v_bill.branch_id
      ) THEN
        RAISE EXCEPTION 'a line of goods is a line of a posted goods received note, from the bill''s supplier, into the bill''s branch, for no more than arrived' USING ERRCODE = 'SE226';
      END IF;
      IF NEW.kind = 'expense' AND NOT EXISTS (
        SELECT 1 FROM public.accounts a
        -- Step 28: or Goods in transit, where import charges wait to be spread over a shipment.
        WHERE a.tenant_id = v_tenant AND a.id = NEW.account_id AND NOT a.is_group AND a.archived_at IS NULL
          AND ((NOT a.is_control AND a.type IN ('expense', 'asset')) OR (a.is_control AND a.control_type = 'goods_in_transit'))
      ) THEN
        RAISE EXCEPTION 'a bill charges an expense or asset account that takes plain entries, or Goods in transit' USING ERRCODE = 'SE234';
      END IF;
    END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  NEW.created_at := now();
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_supplier_bill_line() FROM PUBLIC;
--> statement-breakpoint

-- Not for the app to call. What a posted bill debited to its account for one expense line: the
-- line's amount with its share of the province's tax on the bill, worked exactly as
-- app.post_supplier_bill works it (in proportion, the last expense line taking what is left).
-- Null for anything that is not an expense line of a posted bill of the tenant.
CREATE FUNCTION app.bill_line_charged(p_tenant uuid, p_bill_line uuid) RETURNS numeric
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT y.charged FROM (
      SELECT x.id,
             x.amount + CASE
               WHEN x.tax = 0 THEN 0
               WHEN x.line_no = x.last_no THEN x.tax - coalesce(sum(x.share) OVER (ORDER BY x.line_no ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), 0)
               ELSE x.share
             END AS charged
      FROM (
        SELECT l.id, l.line_no, l.amount, b.provincial_tax AS tax, max(l.line_no) OVER () AS last_no,
               round(b.provincial_tax * l.amount / sum(l.amount) OVER (), 2) AS share
        FROM public.supplier_bill_lines l
        JOIN public.supplier_bills b ON b.tenant_id = l.tenant_id AND b.id = l.bill_id
        WHERE l.tenant_id = p_tenant AND l.kind = 'expense' AND b.status = 'posted'
          AND l.bill_id = (SELECT o.bill_id FROM public.supplier_bill_lines o WHERE o.tenant_id = p_tenant AND o.id = p_bill_line)
      ) x
    ) y WHERE y.id = p_bill_line
  $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.bill_line_charged(uuid, uuid) FROM PUBLIC;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.bill_line_charged(uuid, uuid) FROM app_runtime, anon, authenticated, service_role;
--> statement-breakpoint

-- ── hand-written: what may happen to a shipment ─────────────────────────────────────────────────
-- The guard of a shipment, whoever writes the row, the functions below included. It takes its
-- number here, as it is opened, for the fiscal year of that day. It is never removed. What it
-- is (its number, its supplier, its branch, the day it was opened) never changes; it goes from
-- open to closed or to cancelled, never back, and a cancelled one is not touched again. The
-- times on a row are the database's own. Only a session signed in as postgres itself (a
-- migration, or the removal of a synthetic test company) is not held to this.
CREATE FUNCTION app.check_shipment() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_scope uuid[] := app.tenant_branch_ids();
BEGIN
  IF session_user = 'postgres' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'a shipment is never removed' USING ERRCODE = 'SE257';
  END IF;
  IF NEW.tenant_id IS DISTINCT FROM app.tenant_id() THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NOT isfinite(NEW.opened_on) OR NOT isfinite(coalesce(NEW.gd_date, NEW.opened_on)) OR NOT isfinite(coalesce(NEW.expected_on, NEW.opened_on)) THEN
    RAISE EXCEPTION 'a date on a shipment is a day on the calendar' USING ERRCODE = 'SE263';
  END IF;
  IF TG_OP = 'INSERT' THEN
    -- This guard runs before the policies do, and it takes a number: so only for a member who
    -- may open a shipment in the branch the row names. Anyone else is refused here.
    IF app.tenant_role() IS NULL OR app.tenant_role() NOT IN ('owner', 'accountant') OR app.current_user_id() IS NULL
       OR (v_scope IS NOT NULL AND NOT (NEW.branch_id = ANY (v_scope))) THEN
      RAISE EXCEPTION 'this role cannot open a shipment here' USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF NEW.status <> 'open' THEN
      RAISE EXCEPTION 'a shipment starts open' USING ERRCODE = 'SE256';
    END IF;
    -- The day is Pakistan's, as everywhere in the product; not the session's, which a caller can set.
    IF NEW.opened_on > (now() AT TIME ZONE 'Asia/Karachi')::date THEN
      RAISE EXCEPTION 'that date has not come yet' USING ERRCODE = 'SE263';
    END IF;
    NEW.number := app.next_document_number('SH', NEW.opened_on);
    NEW.closed_at := NULL;
    NEW.closed_by := NULL;
    NEW.created_at := now();
    NEW.updated_at := clock_timestamp();
  ELSE
    IF NEW.id <> OLD.id OR NEW.tenant_id <> OLD.tenant_id OR NEW.number <> OLD.number OR NEW.opened_on <> OLD.opened_on OR NEW.supplier_id <> OLD.supplier_id
       OR NEW.branch_id <> OLD.branch_id OR NEW.created_by <> OLD.created_by OR NEW.created_at <> OLD.created_at THEN
      RAISE EXCEPTION 'what a shipment is and who opened it never change' USING ERRCODE = 'SE257';
    END IF;
    IF OLD.status = 'cancelled' OR (OLD.status = 'closed' AND NEW.status <> 'closed') THEN
      RAISE EXCEPTION 'a closed shipment stays closed, and a cancelled one is not touched again' USING ERRCODE = 'SE256';
    END IF;
    -- Always later than what anyone read before this change, so a screen opened earlier can tell.
    NEW.updated_at := clock_timestamp();
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_shipment() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER shipments_check
  BEFORE INSERT OR UPDATE OR DELETE ON public.shipments
  FOR EACH ROW EXECUTE FUNCTION app.check_shipment();
--> statement-breakpoint
ALTER TABLE public.shipments ENABLE ALWAYS TRIGGER shipments_check;
--> statement-breakpoint

-- The guard of a shipment's goods and of its charges. The shipment's row is held until the
-- transaction ends, so nothing slips on or off while its charges are being spread. Goods are
-- posted goods received notes from the shipment's supplier into its branch, put on or taken
-- off only while the shipment is open. A charge is an expense line of a posted bill of the
-- shipment's branch that was charged to Goods in transit; what it amounts to is read from the
-- bill here; a deposit names an asset account and an expense an expense account, each one that
-- takes plain entries. A charge that has been spread is never taken off, and the only thing
-- ever changed on a charge is that it was spread, which only the function below can say: the
-- app's role has no right to update either table.
CREATE FUNCTION app.check_shipment_part() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_row jsonb;
  v_tenant uuid;
  v_ship public.shipments%ROWTYPE;
  v_scope uuid[] := app.tenant_branch_ids();
  v_amount numeric;
BEGIN
  IF session_user = 'postgres' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    v_row := to_jsonb(OLD);
  ELSE
    v_row := to_jsonb(NEW);
  END IF;
  v_tenant := (v_row->>'tenant_id')::uuid;
  IF v_tenant IS DISTINCT FROM app.tenant_id() THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  -- Held the way an update holds a row: two sessions that each add something and then spread
  -- the charges would otherwise each wait for the other to let go.
  SELECT d.* INTO v_ship FROM public.shipments d WHERE d.tenant_id = v_tenant AND d.id = (v_row->>'shipment_id')::uuid FOR NO KEY UPDATE;
  IF TG_OP = 'UPDATE' THEN
    IF TG_TABLE_NAME <> 'shipment_charges' OR NOT FOUND OR (to_jsonb(OLD)->>'allocation_id') IS NOT NULL
       OR (to_jsonb(NEW) - 'allocation_id') IS DISTINCT FROM (to_jsonb(OLD) - 'allocation_id') THEN
      RAISE EXCEPTION 'the goods and charges of a shipment are replaced, not changed' USING ERRCODE = 'SE265';
    END IF;
    RETURN NEW;
  END IF;
  -- A row of no shipment is left for the foreign key to refuse. Anything else is said only to
  -- a member who could have written the shipment: anyone else is refused by the policies, in
  -- the same words as for a shipment that is not there at all.
  IF FOUND AND app.tenant_role() IN ('owner', 'accountant') AND (v_scope IS NULL OR v_ship.branch_id = ANY (v_scope)) THEN
    IF v_ship.status = 'cancelled' THEN
      RAISE EXCEPTION 'the shipment was cancelled' USING ERRCODE = 'SE256';
    END IF;
    IF TG_TABLE_NAME = 'shipment_receipts' THEN
      IF v_ship.status <> 'open' THEN
        RAISE EXCEPTION 'goods are put on a shipment or taken off it only while it is open' USING ERRCODE = 'SE258';
      END IF;
      IF TG_OP = 'INSERT' AND NOT EXISTS (
        SELECT 1 FROM public.goods_receipts r
        JOIN public.warehouses w ON w.tenant_id = r.tenant_id AND w.id = r.warehouse_id
        WHERE r.tenant_id = v_tenant AND r.id = (v_row->>'receipt_id')::uuid AND r.status = 'posted'
          AND r.supplier_id = v_ship.supplier_id AND w.branch_id = v_ship.branch_id
      ) THEN
        RAISE EXCEPTION 'the goods of a shipment are posted goods received notes from its supplier into its branch' USING ERRCODE = 'SE258';
      END IF;
    ELSE
      IF TG_OP = 'DELETE' AND (v_row->>'allocation_id') IS NOT NULL THEN
        RAISE EXCEPTION 'a charge that has been spread is never taken off' USING ERRCODE = 'SE265';
      END IF;
      IF TG_OP = 'INSERT' THEN
        IF (v_row->>'allocation_id') IS NOT NULL THEN
          RAISE EXCEPTION 'a charge is spread by closing the shipment, not by saying so' USING ERRCODE = 'SE265';
        END IF;
        IF NOT EXISTS (
          SELECT 1 FROM public.supplier_bill_lines l
          JOIN public.supplier_bills b ON b.tenant_id = l.tenant_id AND b.id = l.bill_id
          JOIN public.accounts a ON a.tenant_id = l.tenant_id AND a.id = l.account_id
          WHERE l.tenant_id = v_tenant AND l.id = (v_row->>'bill_line_id')::uuid AND l.kind = 'expense'
            AND b.status = 'posted' AND b.branch_id = v_ship.branch_id AND a.is_control AND a.control_type = 'goods_in_transit'
        ) THEN
          RAISE EXCEPTION 'a charge is a line of a posted bill of the shipment''s branch that was charged to Goods in transit' USING ERRCODE = 'SE259';
        END IF;
        IF (v_row->>'account_id') IS NOT NULL AND NOT EXISTS (
          SELECT 1 FROM public.accounts a
          WHERE a.tenant_id = v_tenant AND a.id = (v_row->>'account_id')::uuid AND NOT a.is_group AND NOT a.is_control AND a.archived_at IS NULL
            AND a.type = CASE v_row->>'class' WHEN 'deposit' THEN 'asset' ELSE 'expense' END
        ) THEN
          RAISE EXCEPTION 'a deposit goes to an asset account and an expense to an expense account, each one that takes plain entries' USING ERRCODE = 'SE259';
        END IF;
        v_amount := app.bill_line_charged(v_tenant, (v_row->>'bill_line_id')::uuid);
        IF v_amount IS NULL OR v_amount <= 0 THEN
          RAISE EXCEPTION 'the bill charged nothing for that line' USING ERRCODE = 'SE259';
        END IF;
        NEW.amount := v_amount;
      END IF;
    END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  NEW.created_at := now();
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_shipment_part() FROM PUBLIC;
--> statement-breakpoint
