-- ── hand-written: stock that is worth more, with no more of it ──────────────────────────────────
-- Not for the app to call: only the function below reaches it. Adds to (or takes from) what a
-- warehouse's holding of an item is worth, leaving the quantity as it is: one move with a value
-- and no quantity, and the balance it leaves. The balance row is held until the transaction
-- ends. Refused where the warehouse holds none of the item, or the value would go below
-- nothing (SE266).
CREATE FUNCTION app.revalue_stock(
  p_tenant uuid, p_user uuid, p_item uuid, p_warehouse uuid, p_date date, p_value numeric, p_source_type text, p_source_id uuid, p_source_line_id uuid
) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_quantity numeric;
  v_value numeric;
BEGIN
  IF p_value IS NULL OR p_value = 0 OR p_value = 'NaN'::numeric OR p_value <> round(p_value, 4) THEN
    RAISE EXCEPTION 'a revaluation has a value, to at most four decimals' USING ERRCODE = 'check_violation';
  END IF;
  SELECT b.quantity, b.value INTO v_quantity, v_value FROM public.stock_balances b
    WHERE b.tenant_id = p_tenant AND b.item_id = p_item AND b.warehouse_id = p_warehouse
    FOR UPDATE;
  IF NOT FOUND OR v_quantity <= 0 OR v_value + p_value < 0 THEN
    RAISE EXCEPTION 'stock that is not held cannot be revalued, nor below nothing' USING ERRCODE = 'SE266';
  END IF;
  v_value := v_value + p_value;
  INSERT INTO public.stock_moves (tenant_id, item_id, warehouse_id, move_date, quantity, value, source_type, source_id, source_line_id, quantity_after, value_after, created_by)
    VALUES (p_tenant, p_item, p_warehouse, p_date, 0, p_value, p_source_type, p_source_id, p_source_line_id, v_quantity, v_value, p_user);
  UPDATE public.stock_balances b SET value = v_value, updated_at = now()
    WHERE b.tenant_id = p_tenant AND b.item_id = p_item AND b.warehouse_id = p_warehouse;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.revalue_stock(uuid, uuid, uuid, uuid, date, numeric, text, uuid, uuid) FROM PUBLIC;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.revalue_stock(uuid, uuid, uuid, uuid, date, numeric, text, uuid, uuid) FROM app_runtime, anon, authenticated, service_role;
--> statement-breakpoint

-- ── hand-written: spreading a shipment's charges ────────────────────────────────────────────────
-- Not for the app to call. The lines of a shipment's goods, in the order charges are spread
-- over them, each with what a charge can be measured by: what the line came into stock at, how
-- many of the item's own unit it was, and their weight and volume from the item's card.
CREATE FUNCTION app.shipment_goods(p_tenant uuid, p_shipment uuid)
  RETURNS TABLE (receipt_line_id uuid, item_id uuid, item_code text, warehouse_id uuid, place bigint, base_quantity numeric, value numeric, weight numeric, volume numeric)
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT g.id, g.item_id, i.code, r.warehouse_id, row_number() OVER (ORDER BY r.receipt_date, r.number, g.line_no), g.base_quantity, m.value,
           g.base_quantity * coalesce(i.weight, 0), g.base_quantity * coalesce(i.volume, 0)
    FROM public.shipment_receipts s
    JOIN public.goods_receipts r ON r.tenant_id = s.tenant_id AND r.id = s.receipt_id AND r.status = 'posted'
    JOIN public.goods_receipt_lines g ON g.tenant_id = r.tenant_id AND g.receipt_id = r.id
    JOIN public.items i ON i.tenant_id = g.tenant_id AND i.id = g.item_id
    JOIN public.stock_moves m ON m.tenant_id = g.tenant_id AND m.source_type = 'goods_receipt' AND m.source_id = r.id AND m.source_line_id = g.id
    WHERE s.tenant_id = p_tenant AND s.shipment_id = p_shipment
  $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.shipment_goods(uuid, uuid) FROM PUBLIC;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.shipment_goods(uuid, uuid) FROM app_runtime, anon, authenticated, service_role;
--> statement-breakpoint

-- One act of the database, whole or not at all: every charge of the shipment that has not been
-- spread yet is spread, on a day, in one journal, and the shipment is closed (it stays closed
-- when a later charge is spread).
--
-- A charge that is part of what the goods cost is shared over the lines of the goods in
-- proportion to its measure, to the paisa, the last line that has any of the measure taking
-- what is left. Then, item by item: of the shipment's quantity of the item, the part the
-- company still holds (in any warehouse; never more than the shipment brought) takes its part
-- of the item's share into stock, the shipment's own warehouse first and then the others, by
-- how much each holds; the rest of the share goes to cost of goods sold. Tax paid at import,
-- deposits and expenses go to their accounts. Goods in transit is credited with every charge.
--
-- Refused: a cancelled shipment (SE256), no charge waiting (SE260), no goods (SE261), a
-- measure none of the goods has (SE262), a date that has not come or is before the goods
-- arrived or a charge was billed (SE263), a closed period.
-- Returns the row written for this spreading.
CREATE FUNCTION app.allocate_shipment(p_shipment uuid, p_date date) RETURNS uuid
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_ship public.shipments%ROWTYPE;
  v_supplier text;
  v_run uuid := gen_random_uuid();
  v_charge record;
  v_line record;
  v_item record;
  v_place record;
  v_row record;
  v_rows jsonb := '[]'::jsonb;
  v_others jsonb := '[]'::jsonb;
  v_measure numeric;
  v_sum numeric;
  v_last bigint;
  v_share numeric;
  v_given numeric;
  v_brought numeric;
  v_held numeric;
  v_kept numeric;
  v_item_stock numeric;
  v_left numeric;
  v_take numeric;
  v_value numeric;
  v_put numeric;
  v_charges integer := 0;
  v_total numeric := 0;
  v_stock numeric := 0;
  v_cogs numeric := 0;
  v_tax numeric := 0;
  v_advance numeric := 0;
  v_journal uuid;
  v_no integer := 0;
BEGIN
  IF v_tenant IS NULL OR v_user IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant') THEN
    RAISE EXCEPTION 'this role cannot spread a shipment''s charges' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'purchase documents are written in read committed transactions' USING ERRCODE = 'SE219';
  END IF;
  SELECT d.* INTO v_ship FROM public.shipments d WHERE d.tenant_id = v_tenant AND d.id = p_shipment FOR UPDATE;
  IF NOT FOUND OR (v_scope IS NOT NULL AND NOT (v_ship.branch_id = ANY (v_scope))) THEN
    RAISE EXCEPTION 'no such shipment in this company' USING ERRCODE = 'SE255';
  END IF;
  IF v_ship.status = 'cancelled' THEN
    RAISE EXCEPTION 'the shipment was cancelled' USING ERRCODE = 'SE256';
  END IF;
  -- Nothing is recorded before it happens. The day is Pakistan's, as everywhere in the product
  -- until a company can choose its own time zone; not the session's, which a caller can set.
  IF p_date IS NULL OR NOT isfinite(p_date) OR p_date > (now() AT TIME ZONE 'Asia/Karachi')::date THEN
    RAISE EXCEPTION 'charges are spread on a day that has come' USING ERRCODE = 'SE263';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.shipment_charges c WHERE c.tenant_id = v_tenant AND c.shipment_id = v_ship.id AND c.allocation_id IS NULL) THEN
    RAISE EXCEPTION 'every charge of the shipment has already been spread' USING ERRCODE = 'SE260';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM app.shipment_goods(v_tenant, v_ship.id)) THEN
    RAISE EXCEPTION 'the shipment has no goods to spread its charges over' USING ERRCODE = 'SE261';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.shipment_receipts s JOIN public.goods_receipts r ON r.tenant_id = s.tenant_id AND r.id = s.receipt_id
    WHERE s.tenant_id = v_tenant AND s.shipment_id = v_ship.id AND r.receipt_date > p_date
  ) OR EXISTS (
    SELECT 1 FROM public.shipment_charges c
    JOIN public.supplier_bill_lines l ON l.tenant_id = c.tenant_id AND l.id = c.bill_line_id
    JOIN public.supplier_bills b ON b.tenant_id = l.tenant_id AND b.id = l.bill_id
    WHERE c.tenant_id = v_tenant AND c.shipment_id = v_ship.id AND c.allocation_id IS NULL AND b.bill_date > p_date
  ) THEN
    RAISE EXCEPTION 'charges are spread on or after the day the goods arrived and each charge was billed' USING ERRCODE = 'SE263';
  END IF;
  PERFORM app.require_open_period(v_tenant, p_date);
  SELECT s.name INTO v_supplier FROM public.suppliers s WHERE s.tenant_id = v_tenant AND s.id = v_ship.supplier_id;

  -- Every balance of the shipment's items is held first, item by item and warehouse by
  -- warehouse, the same way round as every stock document, so two never wait on each other.
  PERFORM 1 FROM public.stock_balances b
    WHERE b.tenant_id = v_tenant AND b.item_id IN (SELECT g.item_id FROM app.shipment_goods(v_tenant, v_ship.id) g)
    ORDER BY b.item_id, b.warehouse_id
    FOR UPDATE;

  -- Each charge, in the order it was put on the shipment.
  FOR v_charge IN
    SELECT c.id, c.class, c.basis, c.account_id, c.amount, l.description, app.bill_line_charged(v_tenant, c.bill_line_id) AS charged
    FROM public.shipment_charges c
    JOIN public.supplier_bill_lines l ON l.tenant_id = c.tenant_id AND l.id = c.bill_line_id
    WHERE c.tenant_id = v_tenant AND c.shipment_id = v_ship.id AND c.allocation_id IS NULL
    ORDER BY c.created_at, c.id
  LOOP
    IF v_charge.charged IS DISTINCT FROM v_charge.amount THEN
      RAISE EXCEPTION 'a charge is no longer what its bill charged' USING ERRCODE = 'SE259';
    END IF;
    v_charges := v_charges + 1;
    v_total := v_total + v_charge.amount;
    IF v_charge.class = 'sales_tax' THEN
      v_tax := v_tax + v_charge.amount;
    ELSIF v_charge.class = 'advance_income_tax' THEN
      v_advance := v_advance + v_charge.amount;
    ELSIF v_charge.class IN ('deposit', 'expense') THEN
      v_others := v_others || jsonb_build_object('account', v_charge.account_id, 'amount', v_charge.amount, 'label', v_charge.description);
    ELSE
      SELECT sum(x.measure), max(x.place) FILTER (WHERE x.measure > 0) INTO v_sum, v_last FROM (
        SELECT g.place, CASE v_charge.basis WHEN 'value' THEN g.value WHEN 'quantity' THEN g.base_quantity WHEN 'weight' THEN g.weight ELSE g.volume END AS measure
        FROM app.shipment_goods(v_tenant, v_ship.id) g) x;
      IF v_sum IS NULL OR v_sum <= 0 THEN
        RAISE EXCEPTION 'the charge "%" cannot be spread by %: none of the goods has any', v_charge.description, v_charge.basis USING ERRCODE = 'SE262';
      END IF;
      v_given := 0;
      FOR v_line IN SELECT g.* FROM app.shipment_goods(v_tenant, v_ship.id) g ORDER BY g.place
      LOOP
        v_measure := CASE v_charge.basis WHEN 'value' THEN v_line.value WHEN 'quantity' THEN v_line.base_quantity WHEN 'weight' THEN v_line.weight ELSE v_line.volume END;
        -- In proportion, never more than is left of the charge; the last line that has any of the measure takes what is left.
        v_share := CASE WHEN v_measure <= 0 THEN 0
                        WHEN v_line.place = v_last THEN v_charge.amount - v_given
                        ELSE least(round(v_charge.amount * v_measure / v_sum, 2), v_charge.amount - v_given) END;
        v_given := v_given + v_share;
        v_rows := v_rows || jsonb_build_object('charge', v_charge.id, 'line', v_line.receipt_line_id, 'item', v_line.item_id, 'place', v_line.place, 'amount', v_share);
      END LOOP;
    END IF;
  END LOOP;

  -- The journal and the row of this spreading come first: what follows points at them.
  -- The balance, and the document behind the journal, are asked when the transaction ends, whatever the caller set before this.
  SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
  INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, branch_id, created_by)
    VALUES (v_tenant, p_date, 'landed_cost', v_run, NULL, left('Import charges of ' || v_ship.number || ' from ' || v_supplier || ' spread over its goods', 500), v_ship.branch_id, v_user)
    RETURNING id INTO v_journal;

  -- Item by item: what the company still holds of what the shipment brought takes its part into stock.
  FOR v_item IN
    SELECT (r.value->>'item')::uuid AS item_id, sum((r.value->>'amount')::numeric) AS amount
    FROM jsonb_array_elements(v_rows) AS r(value) GROUP BY 1 ORDER BY 1
  LOOP
    SELECT sum(g.base_quantity) INTO v_brought FROM app.shipment_goods(v_tenant, v_ship.id) g WHERE g.item_id = v_item.item_id;
    SELECT coalesce(sum(b.quantity), 0) INTO v_held FROM public.stock_balances b WHERE b.tenant_id = v_tenant AND b.item_id = v_item.item_id;
    v_kept := least(v_brought, v_held);
    v_item_stock := CASE WHEN v_kept >= v_brought THEN v_item.amount WHEN v_kept <= 0 THEN 0 ELSE round(v_item.amount * v_kept / v_brought, 2) END;
    -- Into the warehouses that hold the item: those the shipment came into first, then the others, the fullest first.
    v_left := v_kept;
    v_put := 0;
    IF v_item_stock > 0 THEN
      FOR v_place IN
        SELECT b.warehouse_id, b.quantity FROM public.stock_balances b
        WHERE b.tenant_id = v_tenant AND b.item_id = v_item.item_id AND b.quantity > 0
        ORDER BY (b.warehouse_id IN (SELECT g.warehouse_id FROM app.shipment_goods(v_tenant, v_ship.id) g WHERE g.item_id = v_item.item_id)) DESC, b.quantity DESC, b.warehouse_id
      LOOP
        EXIT WHEN v_left <= 0;
        v_take := least(v_left, v_place.quantity);
        v_left := v_left - v_take;
        v_value := CASE WHEN v_left <= 0 THEN v_item_stock - v_put ELSE least(round(v_item_stock * v_take / v_kept, 2), v_item_stock - v_put) END;
        v_put := v_put + v_value;
        IF v_value > 0 THEN
          PERFORM app.revalue_stock(v_tenant, v_user, v_item.item_id, v_place.warehouse_id, p_date, v_value, 'landed_cost', v_run, NULL);
        END IF;
      END LOOP;
    END IF;
    v_stock := v_stock + v_item_stock;
    v_cogs := v_cogs + v_item.amount - v_item_stock;
    -- Kept with each of the item's shares, for what each put into stock (worked below).
    v_rows := (
      SELECT coalesce(jsonb_agg(CASE WHEN (r.value->>'item')::uuid = v_item.item_id THEN r.value || jsonb_build_object('item_amount', v_item.amount, 'item_stock', v_item_stock) ELSE r.value END ORDER BY r.ordinality), '[]'::jsonb)
      FROM jsonb_array_elements(v_rows) WITH ORDINALITY AS r(value, ordinality));
  END LOOP;

  IF v_stock > 0 THEN
    v_no := v_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, v_no, app.control_account(v_tenant, 'inventory'), v_stock, 0, 'Import charges added to what the goods held cost');
  END IF;
  IF v_cogs > 0 THEN
    v_no := v_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, v_no, app.control_account(v_tenant, 'cogs'), v_cogs, 0, 'Import charges on goods that have already gone');
  END IF;
  IF v_tax > 0 THEN
    v_no := v_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, v_no, app.control_account(v_tenant, 'input_tax'), v_tax, 0, 'Sales tax paid at import, ' || v_ship.number);
  END IF;
  IF v_advance > 0 THEN
    v_no := v_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, v_no, app.control_account(v_tenant, 'advance_income_tax'), v_advance, 0, 'Income tax paid at import, ' || v_ship.number);
  END IF;
  FOR v_row IN
    SELECT (o.value->>'account')::uuid AS account_id, sum((o.value->>'amount')::numeric) AS amount, min(o.value->>'label') AS label, count(*) AS charges
    FROM jsonb_array_elements(v_others) AS o(value) GROUP BY 1 ORDER BY 1
  LOOP
    v_no := v_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, v_no, v_row.account_id, v_row.amount, 0, left(CASE WHEN v_row.charges = 1 THEN v_row.label ELSE 'Charges of ' || v_ship.number END, 300));
  END LOOP;
  v_no := v_no + 1;
  INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
    VALUES (v_tenant, v_journal, v_no, app.control_account(v_tenant, 'goods_in_transit'), 0, v_total, 'Import charges of ' || v_ship.number);
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'journal.post', 'journal', v_journal,
      jsonb_build_object('date', p_date, 'source', 'landed_cost', 'sourceId', v_run, 'number', NULL, 'lines', v_no, 'total', v_total::text));

  INSERT INTO public.shipment_allocations (id, tenant_id, shipment_id, allocated_on, total, to_stock, to_cogs, journal_id, created_by)
    VALUES (v_run, v_tenant, v_ship.id, p_date, v_total, v_stock, v_cogs, v_journal, v_user);
  -- Each share, with what of it went into stock: by the running total within its item.
  FOR v_row IN
    SELECT (r.value->>'charge')::uuid AS charge_id, (r.value->>'line')::uuid AS line_id, (r.value->>'item')::uuid AS item_id, (r.value->>'amount')::numeric AS amount,
           (r.value->>'item_amount')::numeric AS item_amount, (r.value->>'item_stock')::numeric AS item_stock,
           sum((r.value->>'amount')::numeric) OVER (PARTITION BY r.value->>'item' ORDER BY r.ordinality) AS running
    FROM jsonb_array_elements(v_rows) WITH ORDINALITY AS r(value, ordinality)
    ORDER BY r.ordinality
  LOOP
    v_value := CASE WHEN v_row.item_amount = 0 THEN 0
                    ELSE round(v_row.item_stock * v_row.running / v_row.item_amount, 2) - round(v_row.item_stock * (v_row.running - v_row.amount) / v_row.item_amount, 2) END;
    INSERT INTO public.landed_cost_allocations (tenant_id, allocation_id, charge_id, receipt_line_id, item_id, amount, to_stock, to_cogs)
      VALUES (v_tenant, v_run, v_row.charge_id, v_row.line_id, v_row.item_id, v_row.amount, v_value, v_row.amount - v_value);
  END LOOP;
  UPDATE public.shipment_charges c SET allocation_id = v_run WHERE c.tenant_id = v_tenant AND c.shipment_id = v_ship.id AND c.allocation_id IS NULL;
  UPDATE public.shipments d SET status = 'closed', closed_at = coalesce(d.closed_at, now()), closed_by = coalesce(d.closed_by, v_user), updated_by = v_user
    WHERE d.tenant_id = v_tenant AND d.id = v_ship.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'shipment.allocate', 'shipment', v_ship.id,
      jsonb_build_object('number', v_ship.number, 'supplier', v_supplier, 'date', p_date, 'charges', v_charges, 'total', v_total::text, 'toStock', v_stock::text,
        'toCostOfGoodsSold', v_cogs::text, 'salesTax', v_tax::text, 'advanceIncomeTax', v_advance::text, 'late', v_ship.status = 'closed', 'journalId', v_journal));
  RETURN v_run;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.allocate_shipment(uuid, date) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.allocate_shipment(uuid, date) TO app_runtime;
--> statement-breakpoint

-- Cancels an open shipment that has nothing on it, with a reason. One with goods or charges on
-- it stays: take them off first (SE264).
CREATE FUNCTION app.cancel_shipment(p_shipment uuid, p_reason text) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_ship public.shipments%ROWTYPE;
BEGIN
  IF v_tenant IS NULL OR v_user IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant') THEN
    RAISE EXCEPTION 'this role cannot cancel a shipment' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT d.* INTO v_ship FROM public.shipments d WHERE d.tenant_id = v_tenant AND d.id = p_shipment FOR UPDATE;
  IF NOT FOUND OR (v_scope IS NOT NULL AND NOT (v_ship.branch_id = ANY (v_scope))) THEN
    RAISE EXCEPTION 'no such shipment in this company' USING ERRCODE = 'SE255';
  END IF;
  IF v_ship.status <> 'open' THEN
    RAISE EXCEPTION 'only an open shipment is cancelled' USING ERRCODE = 'SE256';
  END IF;
  IF p_reason IS NULL OR char_length(btrim(p_reason)) NOT BETWEEN 3 AND 300 THEN
    RAISE EXCEPTION 'a shipment is cancelled with a reason of 3 to 300 characters' USING ERRCODE = 'check_violation';
  END IF;
  IF EXISTS (SELECT 1 FROM public.shipment_receipts s WHERE s.tenant_id = v_tenant AND s.shipment_id = v_ship.id)
     OR EXISTS (SELECT 1 FROM public.shipment_charges c WHERE c.tenant_id = v_tenant AND c.shipment_id = v_ship.id) THEN
    RAISE EXCEPTION 'a shipment with goods or charges on it is not cancelled' USING ERRCODE = 'SE264';
  END IF;
  UPDATE public.shipments d SET status = 'cancelled', cancelled_at = now(), cancelled_by = v_user, cancel_reason = btrim(p_reason), updated_by = v_user
    WHERE d.tenant_id = v_tenant AND d.id = v_ship.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, before, after)
    VALUES (v_tenant, v_user, v_role, 'shipment.cancel', 'shipment', v_ship.id,
      jsonb_build_object('number', v_ship.number, 'status', 'open'), jsonb_build_object('number', v_ship.number, 'status', 'cancelled', 'reason', btrim(p_reason)));
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.cancel_shipment(uuid, text) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.cancel_shipment(uuid, text) TO app_runtime;
